<?php declare(strict_types=1);
namespace Modules\PromptEngine\Services;
use Illuminate\Contracts\Cache\Repository as Cache; use Modules\PromptEngine\Exceptions\PromptTemplateNotFoundException;
final class TemplateLoaderService { public function __construct(private Cache $cache) {} public function load(string $name,array $variables=[],array $required=[]): string { if(!preg_match('/^[a-z0-9_\/-]+$/i',$name)||str_contains($name,'..'))throw new PromptTemplateNotFoundException('Invalid template name.'); $content=$this->content($name); $content=preg_replace_callback('/\{\{>\s*([a-z0-9_\/-]+)\s*\}\}/i',fn($m)=>$this->load($m[1],$variables),$content)??$content; foreach($required as $key)if(!array_key_exists($key,$variables))throw new PromptTemplateNotFoundException('Missing required template variable: '.$key); return preg_replace_callback('/\{\{([A-Z0-9_]+)\}\}/',function($m)use($variables){$v=$variables[$m[1]]??''; return is_array($v)?json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):(string)$v;},$content)??$content; } private function content(string $name): string { $key='prompt-engine.template.'.sha1($name); $read=function()use($name){foreach([(string)config('promptengine.config.override_templates_path'),(string)config('promptengine.config.templates_path')] as $base){$path=rtrim($base,'/\\').DIRECTORY_SEPARATOR.$name.'.md'; if(is_file($path))return (string)file_get_contents($path);} throw new PromptTemplateNotFoundException('Prompt template not found.');}; return config('promptengine.config.cache.enabled',true)?$this->cache->remember($key,(int)config('promptengine.config.cache.ttl',3600),$read):$read(); } }
